const fs = require('fs');

function deepMerge(a, b) {
  if (!b) return a;
  const out = { ...a };
  for (const k of Object.keys(b)) {
    if (
      b[k] &&
      typeof b[k] === 'object' &&
      !Array.isArray(b[k]) &&
      a[k] &&
      typeof a[k] === 'object' &&
      !Array.isArray(a[k])
    ) {
      out[k] = deepMerge(a[k], b[k]);
    } else {
      out[k] = b[k];
    }
  }
  return out;
}

function loadGlobalVars() {
  const envJson = String($env.CASTUO_GLOBAL_VARS_JSON || '').trim();
  let base;
  if (envJson) {
    base = JSON.parse(envJson);
  } else {
    const p = String($env.CASTUO_GLOBAL_VARS_PATH || '').trim();
    if (!p) {
      throw new Error('CASTUO_GLOBAL_VARS_JSON o CASTUO_GLOBAL_VARS_PATH obligatorio (montar config/global_vars.json en el contenedor n8n).');
    }
    base = JSON.parse(fs.readFileSync(p, 'utf8'));
  }
  const ov = String($env.CASTUO_GLOBAL_VARS_OVERRIDE_PATH || '').trim();
  if (ov && fs.existsSync(ov)) {
    base = deepMerge(base, JSON.parse(fs.readFileSync(ov, 'utf8')));
  }
  return base;
}

const cfg = loadGlobalVars();
const sd = $getWorkflowStaticData('global');
sd.castuo_global_vars = cfg;

async function validate(c) {
  const errors = [];
  if (String($env.CASTUO_SKIP_EXTERNAL_VALIDATION || '') === '1') {
    return { isValid: true, errors: [], skipped: true };
  }
  const slack = c.notifications?.slack?.slack_channel;
  if (!slack || !String(slack).trim()) errors.push('Slack: slack_channel vacío');
  const g = c.external_services?.gaiachain;
  const gaiaUrl = g?.api_endpoint && String(g.api_endpoint).trim();
  if (gaiaUrl) {
    try {
      const headers = {};
      if (g.api_key) headers.Authorization = 'Bearer ' + g.api_key;
      const r = await fetch(gaiaUrl, { method: 'GET', headers, redirect: 'manual' });
      if (r.status >= 400) errors.push('GaiaChain HTTP ' + r.status);
    } catch (e) {
      errors.push('GaiaChain: ' + e.message);
    }
  }
  const pbiUrl = c.external_services?.power_bi?.streaming_endpoint && String(c.external_services.power_bi.streaming_endpoint).trim();
  if (pbiUrl) {
    try {
      const r = await fetch(pbiUrl, { method: 'HEAD', redirect: 'manual' });
      if (r.status >= 400) errors.push('Power BI HTTP ' + r.status);
    } catch (e) {
      errors.push('Power BI: ' + e.message);
    }
  }
  return { isValid: errors.length === 0, errors };
}

const validation = await validate(cfg);
return [
  {
    json: {
      castuo: cfg,
      validation,
      persisted_workflow_static: true,
      hint: 'Otros flujos: usar Execute Workflow que devuelva castuo, o CASTUO_GLOBAL_VARS_JSON en cada arranque.',
      ts: new Date().toISOString(),
    },
  },
];
